function report = check_acc00_p0_4_d1_apply_toy(root)
%CHECK_ACC00_P0_4_D1_APPLY_TOY Synthetic enough-events proof of the D1 switch.
root=string(char(java.io.File(char(root)).getCanonicalPath()));addpath(fullfile(root,"scripts","ieeg","acc01"));c=jsondecode(fileread(fullfile(root,"scripts","ieeg","paper","acc00_sim_p0_4_panel_contract.json")));pair=struct("T",100,"signal",[] ,"bad_segments_s",zeros(0,2));fs=double(c.sampling.analysis_hz);t=(0:round(pair.T*fs))'/fs;pair.signal=sin(2*pi*6*t)+.15*sin(2*pi*9*t)+.01*cos(2*pi*3*t);n=50;labelTime=(50+linspace(-.5,.5,n))';z=linspace(-1,1,n)';fold=repmat((1:5)',10,1);events=table(labelTime,z,fold,'VariableNames',{'label_time_s','z_e','crossfit_fold'});
a=acc01_compute_phase_metric_optimized(pair,events,c,RandStream("Threefry","Seed",7),"CrossfitCoefficientMode","refit");b=acc01_compute_phase_metric_optimized(pair,events,c,RandStream("Threefry","Seed",7),"CrossfitCoefficientMode","observed_fixed");da=a.diagnostics.observed_path.crossfit;db=b.diagnostics.observed_path.crossfit;ok=string(da.coefficient_mode)=="refit"&&da.shift_epoch_coefficient_solves>0&&string(db.coefficient_mode)=="observed_fixed"&&db.observed_coefficient_solves>0&&db.shift_epoch_coefficient_solves==0;report=struct("status",ternary(ok,"PASS","FAIL"),"refit_shift_epoch_coefficient_solves",da.shift_epoch_coefficient_solves,"observed_fixed_observed_coefficient_solves",db.observed_coefficient_solves,"observed_fixed_shift_epoch_coefficient_solves",db.shift_epoch_coefficient_solves,"mphase_difference_delta",b.difference-a.difference);assert(ok,"D1 toy apply-path assertion failed.");
end
function x=ternary(c,a,b),if c,x=a;else,x=b;end,end
